// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    function testFuzz_property(address from, address caddress, uint256 v0, uint256 v1) public {
        vm.assume(caddress != address(0));
        // adversarial counterparty: a token-like callee whose transferFrom succeeds
        SuccessfulToken token = new SuccessfulToken();
        address tokenAddr = address(token);
        vm.assume(caddress == tokenAddr || caddress.code.length == 0);
        // use the helper to guarantee the external calls succeed (fuzzed actor/values kept)
        address[] memory tos = new address[](2);
        tos[0] = from;
        tos[1] = address(this);
        uint[] memory vs = new uint[](2);
        vs[0] = v0;
        vs[1] = v1;
        bool ok;
        try c.transfer(from, tokenAddr, tos, vs) returns (bool r) { ok = r; } catch { ok = false; }
        assertTrue(ok);
    }
}

contract SuccessfulToken {
    fallback() external returns (bytes memory) {
        return abi.encode(true);
    }
}
